// ============================================================
// liveCoach — the coach's WORDS, generated by Claude in real time from what the camera measured
// (owner, 2026-10-19: "never a fixed bank of sentences — every correction worded dynamically by the AI,
// exactly for the skeleton data of that moment")
//
// The DETECTION stays deterministic on the device (the expert profiles measure; a rule says WHAT is
// wrong, by how much, in which rep). Claude decides HOW a top coach + physio would SAY it to this
// trainee right now:
//   cue      — during the set: one short, warm, specific sideline correction (Haiku — fast)
//   debrief  — in the rest: a deep, professional analysis of the whole set (Sonnet)
// HONESTY GUARD: the model gets only measured facts and the expert knowledge of the rule; any number in
// its words that is not in the facts → rejected (the device then says its own measured line).
// ============================================================

import Anthropic from '@anthropic-ai/sdk';
import path from 'path';
import { fileURLToPath } from 'url';
import dotenv from 'dotenv';

const __dirname_lc = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.resolve(__dirname_lc, '..', '.env') });

let client = null;
const getClient = () => (client ||= new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY }));

// Measured on the real key (2026-10-19): Sonnet 5 at low effort words a cue in ~1.3–1.6 s in natural,
// correct Hebrew; Opus 5.5 writes the deepest rest analysis in ~8 s. Haiku 4.5 was fast but its Hebrew
// coaching had grammar / meaning errors — not good enough for a professional coach.
// the LIVE words by Sonnet 5 ONLY (owner, 2026-10-21: no Haiku). Speed without a weaker model (measured on the
// real key): thinking OFF for a live line (0.8–1.0 s vs 1.1–1.5 s at effort low), a short output, a cached system
// prompt where it is long enough, and a HEDGE — a 2nd identical request only when the 1st is slow (> 1.3 s)
export const CUE_MODELS = ['claude-sonnet-5'];
export const CUE_HEDGE_MS = 1300;
export const CUE_MODEL = CUE_MODELS[0];
export const DEBRIEF_MODELS = ['claude-opus-5-5', 'claude-sonnet-5'];
export const MAX_CUE_CHARS = 110;
export const MAX_STOP_CHARS = 170;      // the smart stop's short explanation (10–15 words)

const clip = (v, n = 300) => String(v ?? '').replace(/[\x00-\x1f]/g, ' ').slice(0, n);

/** Every number the facts contain (the only numbers the coach may say). */
export function factNumbers(facts) {
  const out = new Set();
  const walk = (v) => {
    if (typeof v === 'number' && Number.isFinite(v)) { out.add(String(Math.round(v))); out.add(String(v)); }
    else if (typeof v === 'string') for (const m of v.match(/\d+(?:\.\d+)?/g) || []) out.add(m);
    else if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') Object.values(v).forEach(walk);
  };
  walk(facts);
  return out;
}

// Direction words: the coach may never REVERSE the measured instruction (in ↔ out, up ↔ down …)
const OPPOSITES = [['החוצה', 'פנימה'], ['למעלה', 'למטה'], ['קדימה', 'אחורה'], ['ימינה', 'שמאלה'], ['outward', 'inward'], ['forward', 'backward']];
const SIDE_WORDS = { left: ['שמאל', 'left'], right: ['ימין', 'right'] };

/** The words keep the facts' directions and the trainee's working side (never reversed / swapped). */
export function directionsKept(text, facts) {
  const t = String(text);
  const known = [facts?.error?.what, facts?.error?.how, ...(facts?.errors || []).flatMap(e => [e.what, e.how])].filter(Boolean).join(' ');
  for (const [a, b] of OPPOSITES) {
    for (const [x, y] of [[a, b], [b, a]]) {
      if (t.includes(y) && !t.includes(x) && known.includes(x) && !known.includes(y)) return false;
    }
  }
  // the side: only the working side given, or a side the facts themselves say (e.g. "the next set: the left leg")
  const said = JSON.stringify([facts?.extras, facts?.body, known]);
  const side = facts?.side;
  const other = side === 'left' ? 'right' : side === 'right' ? 'left' : null;
  if (other && SIDE_WORDS[other].some(w => t.includes(w) && !said.includes(w))) return false;
  if (!side && ['ימין', 'שמאל'].some(w => t.includes(w) && !said.includes(w))) return false;
  return true;
}

/** Readable text (real Hebrew / English letters — a garbled encoding arrives as ??? / mojibake). */
export function readable(t) {
  const str = String(t || '');
  const letters = (str.match(/[א-תA-Za-z]/g) || []).length;
  return letters >= 3 && (str.match(/[?�]/g) || []).length <= letters / 4;
}

/** The words contain no number that was not measured (small counting words like 1–3 are allowed). */
export function numbersGrounded(text, facts) {
  const allowed = factNumbers(facts);
  return (String(text).match(/\d+(?:\.\d+)?/g) || []).every(n => allowed.has(n) || Number(n) <= 3);
}

const COACH_PERSONA = (he) => `You are the world's best ${he ? 'Israeli ' : ''}football / sports coach AND an expert sports physiotherapist, standing next to the trainee and watching THIS movement. You speak ${he ? 'natural spoken Hebrew (masculine singular, like a real Israeli coach on the sideline)' : 'natural spoken English'}.
Ground rules — never break them:
- Use ONLY the measured facts given. Never invent a number, a body part or an event. Numbers only exactly as given.
- The expert knowledge given for each error ("what" / "why" / "how") is the ONLY technique truth. Say the SAME instruction in your own fresh words — never add another instruction, never change a direction (in / out, up / down, forward / back, left / right), never reverse it. If unsure, stay closer to the given words.
- Never praise anything the facts do not show as clean. No generic filler ("good job", "keep going") without a concrete point.
- The trainee may have an amputation / a prosthesis (given in the facts): respect it precisely, never ask a missing limb to do anything.
- Address the trainee ONLY by the given name (or no name) — never any other name.
- Correct, natural Hebrew grammar: the coach SEES the trainee ("אני רואה אותך"), speaks in masculine singular to him.
- If the facts are unclear, garbled or missing, output exactly: SKIP
- Never assume the device (a phone, a laptop) — say "the camera".
- If "kickingProsthesis" is true the kicking leg is a PROSTHESIS: never ask for the ankle, the toes, pointing or flexing the foot — only what a prosthesis can do (the swing from the hip, turning the leg out from the hip, the anchor on the sound leg, balance, the chest over the ball).
- The trainee may train in a SMALL ROOM: never ask them to move the camera or themselves meters away; to be seen better, suggest tilting the camera / keeping the feet in the picture.
- Write every number in DIGITS (e.g. 131, never as words). Mention a body SIDE only if "side" is given, and only that side.
- No lists, no brackets, no emojis, no quotation marks — words that are SPOKEN aloud.`;

/** The prompt of a live cue (pure — tested). */
// The moment the line is for (the device decides WHAT; the AI words it)
const MOMENTS = {
  setup: 'NOW: the trainee is getting into position in front of the camera, maybe in a SMALL ROOM. Say the ONE positioning fix given in "what", in your own words — precise, warm, with authority — at most 12 words, one sentence. Never add another fix.',
  start: 'NOW: the trainee is seen clearly but not yet in the start stance. Tell them, in your own words, exactly what "what" says to do to start — at most 12 words, one sentence, with drive.',
  // THE SMART STOP (owner, 2026-10-25): the same critical error 2–3 times in a block of 3 reps → a short human stop
  stop: 'NOW: you STOP the set for a moment — the SAME critical error keeps repeating ("what"; "why" / "how" = the expert knowledge; "timesInBlock" = how many of the last reps; "bodyNow" = what you see in the whole body). In your own words, as the best professional coach: open with a short natural stop (like "wait, let\'s stop for a second"), then a SHARP, organised fix — EXACTLY what to do on the next rep. If "bodyNow" shows a second clear problem at the same time (e.g. the hands in the pockets AND the toes), name both in ONE ordered sentence (first this, then that) — never a mix; the support leg / the kicking leg named explicitly. 10 to 15 words in all (~5–6 seconds), 1–2 short sentences. Real football terms only — in a PASS drill describe a too-strong pass as "תנופה חזקה מדי" / "מסירה חזקה מדי", never with the word בעיטה / בעט.',
  praise: 'NOW: the last reps were MEASURED correct. Give ONE short, genuine, specific praise for exactly the good point in "what" — 3 to 6 words, one sentence, warm. Never a generic "good job"; never a number.',
  ready: 'NOW: you can see the trainee clearly and the exercise is about to begin. Tell them so and to start — warm, short, at most 8 words. No technique, no numbers.',
  motivate: 'NOW: a natural moment for ONE genuine, warm encouragement (the moment and the intent are in "what"). In your own words, at most 10 words. Never praise a performance, never claim a technique fact, never a number. If the trainee is tired / frustrated: calm and supportive.',
};

export function buildCuePrompt(f) {
  const he = f.lang !== 'en';
  const moment = MOMENTS[f.mode];
  if (moment) {
    const system = `${COACH_PERSONA(he)}
${isPassFacts(f) ? PASS_RULE + '\n' : ''}${moment} ${f.name ? `You may use the name ${clip(f.name, 20)} (not every time).` : ''}
Do not repeat or paraphrase closely any of the recent lines listed. Output ONLY the spoken sentence.`;
    const user = JSON.stringify({
      exercise: clip(f.exercise, 80), sport: clip(f.sport, 40), body: clip(f.body, 120),
      what: clip(f.error?.what, 200), recentLines: (f.recent || []).slice(-4).map(x => clip(x, 90)),
      ...(f.mode === 'stop' ? {
        why: clip(f.error?.why, 300), how: clip(f.error?.how, 300), timesInBlock: f.timesInBlock ?? null,
        bodyNow: (f.bodyNow || []).slice(0, 3).map(x => clip(x, 80)),
        side: f.side === 'left' || f.side === 'right' ? f.side : null, kickingProsthesis: !!f.kickingProsthesis,
      } : {}),
    });
    return { system, user };
  }
  const system = `${COACH_PERSONA(he)}
${isPassFacts(f) ? PASS_RULE + '\n' : ''}NOW: the trainee is IN THE MIDDLE OF A SET. Give ONE immediate correction, like a shout from the sideline of the best professional coach: sharp, technical, specific to THIS rep — 3 to 5 words (never more than 6), ONE COMPLETE short sentence, NO name.
WHOLE BODY, ONE CHAIN (owner, 2026-10-21): "error" is what the device MEASURED (the leg / the movement); "bodyNow" is what the coach's eyes see in the WHOLE body (chest, pelvis, posture, support leg). Treat them as ONE movement chain: when the body causes the leg error (e.g. the chest leaning back → the leg swings up; the pelvis open → the foot does not turn out), name the ROOT in the body and its effect on the leg in one instruction; otherwise give the single most important fix. Never generic, never filler, never a vague 'focus' — a concrete action a top coach would shout (it must be SAID in under 2 seconds, the next pass is coming; the deep why / how is said in the rest). It must tell them what to do on the very next rep — exactly the instruction of "what" / "how", nothing else.
${f.tone === 'calm' ? 'The trainee is tired / frustrated right now: say it calmly and supportively, one simple thing.' : ''}
Do not repeat or paraphrase closely any of the recent cues listed.${(f.previousForThisError || []).length ? ' This SAME error is repeating — "previousForThisError" lists what you already told; give the same fix from a DIFFERENT angle (another body part of the chain, an external focus, a feel / image), never the same words or the same structure.' : ''} Output ONLY the spoken sentence.`;
  const user = JSON.stringify({
    exercise: clip(f.exercise, 80), sport: clip(f.sport, 40), body: clip(f.body, 120),
    previousForThisError: (f.previousForThisError || []).slice(-3).map(x => clip(x, 90)),
    bodyNow: (f.bodyNow || []).slice(0, 3).map(x => clip(x, 80)),
    side: f.side === 'left' || f.side === 'right' ? f.side : null,
    kickingProsthesis: !!f.kickingProsthesis,
    rep: f.rep ?? null, error: {
      what: clip(f.error?.what, 200), why: clip(f.error?.why, 300), how: clip(f.error?.how, 300),
      measured: f.error?.measured ?? null, target: clip(f.error?.target, 80), timesThisSet: f.error?.times ?? null,
    },
    recentCues: (f.recent || []).slice(-4).map(x => clip(x, 90)),
  });
  return { system, user };
}

/** The prompt of the exercise briefing (pure — tested). */
export function buildBriefingPrompt(f) {
  const he = f.lang !== 'en';
  const system = `${COACH_PERSONA(he)}
NOW: the exercise is about to begin. Introduce and TEACH it to THIS trainee like the best coach + physiotherapist: what the exercise is for, then the technique — ONLY the steps and the key point given, in your own fresh words, adapted to the trainee's body (a prosthesis / crutches as given) — and end with a short cue to get ready. About 45–75 words, flowing spoken sentences. ${f.name ? `Address the trainee as ${clip(f.name, 20)} once.` : ''}
Output ONLY the spoken text.`;
  const user = JSON.stringify({
    exercise: clip(f.exercise, 80), sport: clip(f.sport, 40), body: clip(f.body, 120),
    sets: f.sets ?? null, reps: clip(f.reps, 20),
    steps: (f.steps || []).slice(0, 8).map(x => clip(x, 200)), keyPoint: clip(f.safety, 300), setup: clip(f.setup, 200),
  });
  return { system, user };
}

/** The prompt of the rest's analysis (pure — tested). */
export function buildDebriefPrompt(f) {
  const he = f.lang !== 'en';
  const system = `${COACH_PERSONA(he)}
NOW: the REST between sets. You are the expert in the locker room analysing the set that just ended, for THIS trainee, from the measured log. Speak about 70–130 words, in flowing spoken sentences:
${f.prefetch ? '1. Do NOT open with the set in numbers (the coach says them first) and give frequencies in words ("in most passes", "in a few") — never as counts.' : '1. The set in numbers (reps / seconds, accuracy — if accuracy is null say nothing about it).'} "reps" are COUNTED reps — never call them clean, perfect or good unless "errors" is empty.
2. The most important thing to fix (safety first, then what happened most): what happened, how often, the measured value vs. the target when given, WHY it matters biomechanically / for injury, and HOW to fix it — a precise, practical instruction or feel.
3. COVER EVERY main problem of the set (owner, 2026-10-25): every item of "setProblems" (the device's + the coach's eyes', with the reps it happened in) gets its own short sentence — what and how to fix — most important first. Items in "fixedAfterStop" were stopped for during the set and did NOT come back: say they are fixed (genuine praise), never as a problem.
4. What was good — ONLY items listed in "measuredClean". If "judgedNothing" is true, say honestly that this set's technique could not be measured clearly from the camera (and what would help) — NEVER call the set clean or perfect.
5. ONE clear goal for the next set (or, if lastSet, what to take to next time).
If nothing was measured (attempts 0 and no errors) say honestly that you could not see the movement clearly and what to do so you can.
"visualNotes" are what a vision model saw in single frames — weaker evidence than the measurement: use a note only if it agrees with the measured errors / clean items, never to contradict them, and never invent a number from it.
"oneOffs" (owner, 2026-10-25) = single slips that happened ONCE in their block of reps and were NOT said during the set: mention the most relevant one in ONE short sentence — "I noticed in rep X you did Y — watch it in the next set" (in your own words).
Then add the spoken extras given (the leg switch / a mental cue), if any.
Return ONLY JSON: {"speech":"<the spoken analysis>","card":[{"kind":"fix|good|focus|note","title":"<short line>","detail":["<short line>", ...]}]} — the card is a short written version of the same analysis (max 5 items).`;
  const user = JSON.stringify({
    exercise: clip(f.exercise, 80), sport: clip(f.sport, 40), body: clip(f.body, 120), name: clip(f.name, 20),
    setNo: f.setNo ?? null, lastSet: !!f.lastSet, unit: f.unit === 'sec' ? 'seconds' : 'reps',
    reps: f.reps ?? 0, accuracy: typeof f.accuracy === 'number' ? Math.round(f.accuracy) : null,
    attempts: f.attempts ?? 0, partialReps: f.partial ?? 0,
    errors: (f.errors || []).slice(0, 6).map(e => ({
      what: clip(e.what, 200), times: e.n, of: e.judged, severity: e.severity,
      measuredAvg: e.measured ?? null, target: clip(e.target, 80), why: clip(e.why, 300), how: clip(e.how, 300),
    })),
    measuredClean: (f.clean || []).slice(0, 4).map(x => clip(x, 80)),
    extras: (f.extras || []).filter(Boolean).map(x => clip(x, 160)),
    visualNotes: (f.visual || []).filter(Boolean).slice(-6).map(x => clip(x, 160)),
    oneOffs: (f.oneOffs || []).slice(0, 4).map(o => ({ rep: o?.rep ?? null, what: clip(o?.what, 100) })).filter(o => o.what),
    setProblems: (f.setProblems || []).slice(0, 6).map(p => ({ what: clip(p?.what, 100), times: p?.times ?? null, reps: (p?.reps || []).slice(0, 6), critical: !!p?.critical })).filter(p => p.what),
    fixedAfterStop: (f.fixedAfterStop || []).slice(0, 4).map(x => clip(x, 100)),
    judgedNothing: !!f.judgedNothing,
  });
  return { system, user };
}

// (the Claude 5 models think adaptively: `effort` sets how much — low for a sideline cue; no temperature)
async function ask(model, { system, user }, maxTokens, timeoutMs, effort = null) {
  const res = await getClient().messages.create({
    model, max_tokens: maxTokens,
    // (the system prompt is cached — cheaper and faster when it passes the model's cache minimum)
    system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: user }],
    // 'off' = a live line with NO thinking (the fastest Sonnet answer); otherwise the adaptive effort
    ...(effort === 'off' ? { thinking: { type: 'disabled' } } : effort ? { output_config: { effort } } : {}),
  }, { timeout: timeoutMs, maxRetries: 0 });
  return (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
}

/** A live cue, or null (the device then says its own measured line). */
/** What went wrong with the Anthropic API (for the server log and the trainee's screen). */
export function aiErrorKind(err) {
  const m = String(err?.message || err || '');
  const st = err?.status;
  if (/credit balance/i.test(m)) return 'credit';
  if (st === 401 || /authentication|api[_ -]?key/i.test(m)) return 'auth';
  if (st === 429 || /rate.?limit/i.test(m)) return 'rate';
  if (st === 529 || /overloaded/i.test(m)) return 'overloaded';
  if (/timed? ?out|timeout/i.test(m)) return 'timeout';
  return 'error';
}

const isModelError = (err) => /model|not_found|404|not supported/i.test(String(err?.message || err));

// A PASS is never a "kick", and a correction never "יפה" (owner, 2026-10-21)
const PASS_RE = /pass|מסיר/i;
export const isPassFacts = (f) => !!f?.isPass || !!f?.passDrill || PASS_RE.test(String(f?.exercise || ''));
const BANNED_PASS = /(^|[\s,.!—-])(ב?לבעוט|תבעט|בעט|בועט|(ה|ב|ל)?בעיט(ה|ות)|יפה|kick(s|ing)?)(?=$|[\s,.!—-])/i;
export const passWordsOk = (text, f) => !isPassFacts(f) || !BANNED_PASS.test(String(text || ''));
export function passWordsFix(s) {
  return String(s || '')
    .replace(/(^|[\s,.!—-])ב?לבעוט(?=$|[\s,.!—-])/g, '$1למסור').replace(/(^|[\s,.!—-])תבעט(?=$|[\s,.!—-])/g, '$1תמסור')
    .replace(/(^|[\s,.!—-])בעט(?=$|[\s,.!—-])/g, '$1מסור').replace(/(^|[\s,.!—-])(ה|ב|ל)?בעיטה(?=$|[\s,.!—-])/g, (m, a, p) => `${a}${p || ''}מסירה`)
    .replace(/(^|[\s,.!—-])(ה|ב|ל)?בעיטות(?=$|[\s,.!—-])/g, (m, a, p) => `${a}${p || ''}מסירות`)
    .replace(/(^|\s)יפה(?=$|[\s,.!—-])/g, '$1').replace(/\s{2,}/g, ' ').trim();
}
const PASS_RULE = 'This is a PASS drill: never use the words בעט / תבעט / לבעוט / בעיטה (kick) or יפה — say מסירה / מסור and professional passing terms.';

export async function generateCue(facts, { timeoutMs = 3000, askFn = ask } = {}) {
  // garbled / empty facts → the AI would guess: never (the device says its own measured line)
  if (!readable(facts?.error?.what)) return null;
  const prompt = buildCuePrompt(facts);
  for (const model of CUE_MODELS) {
    let raw;
    try { raw = await hedged(() => askFn(model, prompt, facts.mode === 'stop' ? 140 : 80, facts.mode === 'stop' ? Math.max(timeoutMs, 4500) : timeoutMs, 'off'), facts.mode === 'stop' ? 2500 : CUE_HEDGE_MS); } catch (err) { if (isModelError(err)) continue; throw err; }
    const text = String(raw || '').replace(/["“”«»]/g, '').replace(/\s+/g, ' ').trim();
    if (!text || /^SKIP/i.test(text) || text.length > (facts.mode === 'stop' ? MAX_STOP_CHARS : MAX_CUE_CHARS) || !numbersGrounded(text, facts) || !directionsKept(text, facts)) return null;
    if (!passWordsOk(text, facts)) return null;                                  // a pass is never a "kick" / "יפה"
    if ((facts.recent || []).some(r => r && r.trim() === text)) return null;   // never the same words twice
    if (wordCount(text) <= MAX_CUE_WORDS || facts.mode) return text;
    // too long (owner, 2026-10-21): the SAME instruction asked again, at most 6 words, whole (never a cut sentence)
    let short = null;
    try {
      const again = { system: `${prompt.system}\nYour answer "${clip(text, 120)}" was too long. Say the SAME instruction in at most ${MAX_CUE_WORDS} words — one complete sentence. Output ONLY it.`, user: prompt.user };
      short = String(await askFn(model, again, 60, 1200, 'off') || '').replace(/["“”«»]/g, '').replace(/\s+/g, ' ').trim();
    } catch { short = null; }
    if (short && wordCount(short) <= MAX_CUE_WORDS && !/^SKIP/i.test(short) && numbersGrounded(short, facts) && directionsKept(short, facts) && passWordsOk(short, facts)) return short;
    // (still long: its first whole clause when that alone is a full short instruction; else the device's line)
    const first = text.split(/[,—–;.!]/)[0].trim();
    return wordCount(first) >= 3 && wordCount(first) <= MAX_CUE_WORDS ? first : null;
  }
  return null;
}
export const MAX_CUE_WORDS = 6;
/** The first answer of `fn`, with a 2nd identical call started only if the 1st has not answered after `ms`. */
export function hedged(fn, ms) {
  return new Promise((resolve, reject) => {
    let done = false, fails = 0, started = 1;
    const run = () => fn().then((v) => { if (!done) { done = true; resolve(v); } }, (e) => { if (++fails >= started && !done) { done = true; reject(e); } });
    run();
    setTimeout(() => { if (!done) { started = 2; run(); } }, ms);
  });
}
// (the Hebrew object particle "את" is not counted — it is barely heard; 6 words = the length of a short shout)
const wordCount = (t) => String(t || '').trim().split(/\s+/).filter(w => w && w !== 'את').length;

/** The spoken briefing of an exercise, or null (the device then says the written explanation). */
export async function generateBriefing(facts, { timeoutMs = 18000, askFn = ask } = {}) {
  const steps = facts?.steps || [];
  if (!readable(facts?.exercise) || !steps.length || steps.some(x => !readable(x))) return null;
  const prompt = buildBriefingPrompt(facts);
  // the guards judge it against the given technique (its directions, its numbers)
  const ground = { ...facts, error: { what: steps.join(' '), how: facts.safety || '' } };
  for (const model of CUE_MODELS) {
    let raw;
    try { raw = await askFn(model, prompt, 800, timeoutMs, 'low'); } catch (err) { if (isModelError(err)) continue; throw err; }
    const text = String(raw || '').replace(/["“”«»]/g, '').replace(/\s+/g, ' ').trim();
    if (!text || /^SKIP/i.test(text) || text.length < 40 || text.length > 700) return null;
    if (!numbersGrounded(text, facts) || !directionsKept(text, ground)) return null;
    return text;
  }
  return null;
}

// ---- THE EYES: one frame at the contact of a SHADOW pass (a virtual ball — judge the kicking foot itself) ----
// the eyes by Haiku 4.5 first (owner, 2026-10-21 — measured: Haiku 3.1–3.4 s, Sonnet 5 2.6–3.5 s on one image)
export const VISION_MODELS = ['claude-sonnet-5'];
// the eyes' FIXED categories (owner, 2026-10-25): one name per body part — the same fault is recognised as the same
export const VISION_CATEGORIES = ['support_leg', 'chest', 'pelvis', 'swing', 'contact', 'arms_hands', 'head_shoulders', 'balance'];
export function visionCategory(code) {
  const c = String(code || '').toLowerCase();
  if (VISION_CATEGORIES.includes(c)) return c;
  if (/support|stance|plant|knee_lock|knee_stiff/.test(c)) return 'support_leg';
  if (/chest|lean|torso|trunk|posture/.test(c)) return 'chest';
  if (/pelvis|hip/.test(c)) return 'pelvis';
  if (/swing|kick|back_?swing|follow/.test(c)) return 'swing';
  if (/contact|toe|ankle|foot|laces|inside/.test(c)) return 'contact';
  if (/hand|arm|pocket/.test(c)) return 'arms_hands';
  if (/head|gaze|shoulder|neck/.test(c)) return 'head_shoulders';
  if (/balance|stab/.test(c)) return 'balance';
  return c.replace(/[^a-z0-9_]/g, '').slice(0, 40);
}   // (owner, 2026-10-21: Sonnet 5 only)
export function buildPassVisionPrompt(f) {
  const system = `You are an expert football coach and sports physiotherapist judging ONE camera frame taken at the moment of a SHADOW inside-foot PASS (there is no real ball; judge the kicking foot and leg themselves). The kicking leg is the trainee's ${f.side === 'left' ? 'LEFT' : f.side === 'right' ? 'RIGHT' : 'moving'} leg (anatomical side; the image may be mirrored). ${f.body ? `Body: ${clip(f.body, 120)}.` : ''}
Judge only what is clearly visible. For each item give a value and your confidence 0..1 (below 0.6 when the foot is blurred, cut off or hidden).
- contact: which surface of the kicking foot faces the pass direction — "inside" (the foot turned out, the arch facing forward), "laces" (the instep, toes pointed down), "toe" (the foot pointing forward, the tip leading), or "unclear".
- ankleLocked: true if the kicking foot is held firm (toes pulled up / neutral), false if the foot is floppy / toes dropped, null if unclear.
Return ONLY JSON: {"contact":{"value":"inside|laces|toe|unclear","confidence":0.0},"ankleLocked":{"value":true|false|null,"confidence":0.0}}`;
  return { system };
}
export async function generatePassVision(f, { timeoutMs = 5500, askFn = null } = {}) {
  const frame = String(f?.frame || '');
  if (frame.length < 1000 || frame.length > 400000) return null;
  const { system } = buildPassVisionPrompt(f);
  for (const model of VISION_MODELS) {
    try {
      const raw = askFn ? await askFn(model, system, frame)
        : (await getClient().messages.create({
          model, max_tokens: 300, system,
          messages: [{ role: 'user', content: [{ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: frame } }, { type: 'text', text: 'Judge this pass frame.' }] }],
          ...(model.startsWith('claude-sonnet-5') ? { output_config: { effort: 'low' } } : {}),
        }, { timeout: timeoutMs, maxRetries: 0 })).content.filter(b => b.type === 'text').map(b => b.text).join('');
      const m = String(raw).match(/\{[\s\S]*\}/);
      const j = m ? JSON.parse(m[0]) : null;
      const item = (o, vals) => (o && vals.includes(o.value) && typeof o.confidence === 'number' ? { value: o.value, confidence: Math.max(0, Math.min(1, o.confidence)) } : null);
      return j ? { contact: item(j.contact, ['inside', 'laces', 'toe', 'unclear']), ankleLocked: item(j.ankleLocked, [true, false, null]) } : null;
    } catch (err) {
      if (!isModelError(err)) throw err;
    }
  }
  return null;
}

// ---- THE WHOLE-BODY EYES (owner, 2026-10-20): the coach looks at EVERYTHING — posture, arms, trunk, head,
// balance, the legs and feet, anything that stops a correct execution (hands in pockets was only an example) ----
export function buildBodyVisionPrompt(f) {
  const he = f.lang !== 'en';
  const system = `You are the world's best coach and sports physiotherapist watching ONE camera frame of a trainee in the middle of THIS exercise: "${clip(f.exercise, 80)}"${f.sport ? ` (${clip(f.sport, 40)})` : ''}. ${f.body ? `Body: ${clip(f.body, 120)} — respect it precisely, never ask a missing / prosthetic limb to do anything it cannot.` : ''}
${(f.keyPoints || []).length ? `The exercise's correct technique: ${(f.keyPoints || []).slice(0, 6).map(x => clip(x, 120)).join(' | ')}.` : ''}
${f.legsImage ? 'A second image is a close-up of the legs and feet of the same moment.' : ''}${f.composite ? 'The image has TWO panels of the same moment: LEFT = the whole body, RIGHT = a close-up of the legs and feet.' : ''}${f.isPass ? ` It is a SHADOW inside-foot pass (no real ball); the kicking leg is the ${f.side === 'left' ? 'LEFT' : f.side === 'right' ? 'RIGHT' : 'moving'} (anatomical) leg.` : ''}
${f.kickingProsthesis ? `The KICKING leg is the trainee's PROSTHESIS (the ${f.side === 'left' ? 'LEFT' : f.side === 'right' ? 'RIGHT' : ''} leg): its ankle is fixed — NEVER judge or mention the ankle lock, the toes or which surface of the foot meets the ball. Judge the prosthesis kick by its real technique: the swing driven from the HIP (not the knee), the leg turned out from the hip, the weight anchored on the sound support leg, the chest over the ball, the arms for balance.
` : ''}${f.isPass || f.kickingProsthesis || isPassFacts(f) ? 'The ball is VIRTUAL (drawn on the screen, not in the camera): never report a missing / unseen ball.\n' : ''}${f.isPass || f.kickingProsthesis ? 'This is a PASS: if it was executed like a POWER KICK (a big back-swing, a knee snap, the leg swinging high / hard) report it as a MAJOR finding "pass_like_kick" — a pass is short, controlled, from the hip.\n' : ''}${isPassFacts(f) ? PASS_RULE + '\n' : ''}${f.goal ? `Today's training goal: ${clip(f.goal, 80)}.\n` : ''}Never praise what was technically wrong.
Look at the WHOLE body, never the kicking leg alone (owner, 2026-10-21): the CHEST (over the ball / leaning back / collapsed), the overall POSTURE and trunk, the PELVIS (square, rotating, dropping, shifting), the SUPPORT leg (knee soft, foot planted, weight on it), the head and gaze, the arms for balance, and the working leg and foot — anything that prevents a correct, safe execution of THIS exercise. Judge the whole chain: a fault in the chest / posture / pelvis that spoils the movement is as important as the leg. Arms simply hanging beside the body are NOT "hands in the pockets" — report that only if the hands are clearly inside the pockets.
${f.atPeak ? 'This frame is the PEAK of the rep (the moment of contact / the end of the swing) — judge the movement at its decisive moment; never report "no movement" / "static" / "not executing".\n' : ''}The image is the RAW CAMERA of the real trainee — if any drawn figure / avatar / skeleton lines ever appear, ignore them completely; judge only the real body.
Scan EVERY part, top to bottom, in detail: head and gaze, shoulders, arms and hands (look carefully — are the hands INSIDE the pockets? arms out for balance?), chest, pelvis, the support leg, the working leg, and the CONTACT.${f.isPass ? ' THE CONTACT (use the legs close-up): which surface of the kicking foot meets the ball line — the INSIDE of the foot (the arch facing the target, the foot turned out), the LACES (the instep), or the TOES (the foot pointing forward, the tip leading). Always fill "ct"; a toe / laces contact you can see is ALSO a finding {"c":"contact","s":"M"}.' : ''}
"c" MUST be ONE of these fixed categories (never another code): ${VISION_CATEGORIES.join(' | ')}.
Report ONLY what is clearly visible. Return ONLY this COMPACT JSON (short keys — every token costs time):
{"f":[{"c":"short_snake_case_code","s":"M|m","p":0.0,"w":"<${he ? 'Hebrew' : 'English'}, at most 6 words: what you saw>","q":"<${he ? 'Hebrew' : 'English'}, 3-6 words: ONE whole-chain instruction for the next rep — link the body to the leg when they are connected (e.g. the chest back → the leg swings up)>"}],"g":"<${he ? 'Hebrew' : 'English'}, 3-5 words of genuine praise, or empty>","gp":0.0${f.isPass ? ',"ct":"inside|laces|toe|unclear","cp":0.0,"al":true|false|null,"ap":0.0' : ''}}
("s": "M" = major, "m" = minor; "p" = how sure you are it is REALLY visible in this frame: 0.9 = clearly seen, 0.75 = seen, 0.5 = a guess — be honest, a clear fault is 0.8+; "gp" = the praise's confidence.)
Coach like the best professional: see the movement as ONE chain (support foot → knee → pelvis → chest → the working leg → the foot); name the ROOT cause of what went wrong, not a symptom; precise football terms, never generic filler.
"major" ONLY = a real injury risk, or a fault in THIS exercise's core technique (for a pass: the contact surface, the swing, the support leg, the body over the ball); for a pass the chest over the ball, the pelvis and the support leg ARE core technique; the arms / the hands = "minor" unless it really endangers or breaks the core technique. The cue: at most 6 words. At most 2 findings, the most important first; at most 1 "good". Be brief — the answer is needed within 2 seconds. Output compact JSON only — no code fences, no text before or after. No numbers inside the texts. Natural spoken ${he ? 'Hebrew (masculine singular)' : 'English'}. If the body is not clearly visible return {"f":[],"g":""}.`;
  return { system };
}
export async function generateBodyVision(f, { timeoutMs = 9000, askFn = null } = {}) {
  const frame = String(f?.frame || '');
  if (frame.length < 1000 || frame.length > 600000) return null;
  const legs = String(f?.legsFrame || '');
  const { system } = buildBodyVisionPrompt({ ...f, isPass: f.isPass && !f.kickingProsthesis, legsImage: legs.length > 1000 });
  const content = [{ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: frame } }];
  if (legs.length > 1000 && legs.length < 600000) content.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: legs } });
  const said = (Array.isArray(f.recent) ? f.recent : []).slice(-4).map(x => clip(x, 80)).filter(Boolean);
  content.push({ type: 'text', text: said.length ? `Judge this moment. Already told this set (if the same fault repeats, give the fix from a DIFFERENT angle — never these words): ${said.join(' | ')}` : 'Judge this moment.' });
  for (const model of VISION_MODELS) {
    try {
      const raw = askFn ? await askFn(model, system, content)
        : (await getClient().messages.create({
          model, max_tokens: 300, system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }], messages: [{ role: 'user', content }],
          output_config: { effort: 'low' },
        }, { timeout: timeoutMs, maxRetries: 0 })).content.filter(b => b.type === 'text').map(b => b.text).join('');
      const m = String(raw).match(/\{[\s\S]*\}/);
      let j = null;
      try { j = m ? JSON.parse(m[0]) : null; } catch { j = null; }
      if (!j) return null;
      // the compact answer → the full structure the app uses (the cue doubles as "what" — the rest's log)
      if (Array.isArray(j.f) || typeof j.g === 'string') {
        j = {
          findings: (j.f || []).map(x => ({ code: visionCategory(x?.c), severity: x?.s === 'M' ? 'major' : 'minor', confidence: x?.p, cue: x?.q, what: x?.w || x?.q })),
          good: j.g ? [{ text: j.g, confidence: typeof j.gp === 'number' ? j.gp : 0.7 }] : [],
          contact: j.ct ? { value: j.ct, confidence: j.cp } : null,
          ankleLocked: j.al !== undefined && j.ap !== undefined ? { value: j.al, confidence: j.ap } : null,
        };
      }
      const conf = (x) => (typeof x === 'number' ? Math.max(0, Math.min(1, x)) : 0);
      const txt = (x, n) => clip(x, n).trim();
      // honesty guards on every finding: readable words, no invented numbers, a short cue
      const okText = (t) => readable(t) && !/\d/.test(t);
      const findings = (Array.isArray(j.findings) ? j.findings : []).slice(0, 3).map(x => ({
        code: String(x?.code || '').toLowerCase().replace(/[^a-z0-9_]/g, '').slice(0, 40),
        severity: x?.severity === 'major' ? 'major' : 'minor', confidence: conf(x?.confidence),
        cue: txt(x?.cue, 80), what: txt(x?.what, 200), why: txt(x?.why, 220), how: txt(x?.how, 220),
      })).filter(x => x.code && okText(x.cue) && okText(x.what))
        .filter(x => !(isPassFacts(f) && /ball/.test(x.code) && /visib|missing|no_ball|not_seen|absent/.test(x.code)))   // (a virtual ball)
        .map(x => (isPassFacts(f) ? { ...x, cue: passWordsFix(x.cue), what: passWordsFix(x.what), how: passWordsFix(x.how) } : x));
      const good = (Array.isArray(j.good) ? j.good : []).slice(0, 2).map(x => ({ text: txt(x?.text, 80), confidence: conf(x?.confidence) }))
        .map(x => (isPassFacts(f) ? { ...x, text: passWordsFix(x.text) } : x)).filter(x => okText(x.text));
      const item = (o, vals) => (o && vals.includes(o.value) && typeof o.confidence === 'number' ? { value: o.value, confidence: conf(o.confidence) } : null);
      return { findings, good, contact: item(j.contact, ['inside', 'laces', 'toe', 'unclear']), ankleLocked: item(j.ankleLocked, [true, false, null]) };
    } catch (err) {
      if (!isModelError(err)) throw err;
    }
  }
  return null;
}

/** The rest's analysis { speech, card }, or null. */
export async function generateDebrief(facts, { timeoutMs = 25000, askFn = ask } = {}) {
  if ((facts?.errors || []).some(e => !readable(e?.what)) || (facts?.name && !readable(facts.name) && String(facts.name).length > 0 && /[?�]/.test(facts.name))) return null;
  const prompt = buildDebriefPrompt(facts);
  for (const model of DEBRIEF_MODELS) {
    try {
      const raw = await askFn(model, prompt, 1500, timeoutMs, 'low');
      const m = raw.match(/\{[\s\S]*\}/);
      const j = m ? JSON.parse(m[0]) : null;
      if (!j || typeof j.speech !== 'string' || j.speech.length < 20 || /^SKIP/i.test(j.speech)) return null;
      if (!numbersGrounded(j.speech, facts) || !directionsKept(j.speech, facts)) return null;
      const card = (Array.isArray(j.card) ? j.card : []).slice(0, 5)
        .filter(it => it && typeof it.title === 'string')
        .map(it => ({ kind: ['fix', 'good', 'focus', 'note'].includes(it.kind) ? it.kind : 'note', title: clip(it.title, 160), detail: (Array.isArray(it.detail) ? it.detail : []).slice(0, 4).map(d => clip(d, 220)) }))
        .filter(it => numbersGrounded(`${it.title} ${it.detail.join(' ')}`, facts));
      return { speech: j.speech.replace(/\s+/g, ' ').trim(), card };
    } catch (err) {
      // a model this key cannot use → the next one; anything else → the device's own analysis
      if (!isModelError(err)) throw err;
    }
  }
  return null;
}
